#!/usr/bin/env python3
"""check_system_md.py — hygiene gate for SYSTEM.md. Generated by
bootstrap-system-md (contract v5); adjust CONFIG. Rationale:
docs/system-md-contract.md.

The cap is in BYTES. Lines are reported, never gated — a line cap is gamed
by widening lines.

LEVEL controls which checks run:
  small : byte cap (WARN 90% / FAIL 100%), long-line WARN, accretion
          detector (dates outside ledgers), shipped markers in Deferred,
          deferred items missing a "do when" trigger
  medium: + per-section byte budgets (FAIL), baselines sidecar, extraction
          warning that persisted across the last two baselines → FAIL,
          --stamp writes the header's revision line from git
  large : + enforcement-point verification (.system_md_enforcement.json),
          WARN for every inv id with no pin, --update-baselines requires
          --reason

Usage: check_system_md.py [--stamp] [--update-baselines --reason "<text>"]
"""
import json, re, subprocess, sys
from datetime import date
from pathlib import Path

# ---- CONFIG ----
LEVEL = "medium"                          # "small" | "medium" | "large"
SYSTEM_MD = Path("SYSTEM.md")
SIDECAR = Path(".system_md_baselines.json")
ENFORCEMENT_MAP = Path(".system_md_enforcement.json")
CAP_BYTES = 40_000                        # ≈ 1.15 × bootstrap size
WARN_AT = 0.90
LONG_LINE = 160                           # readability WARN, prose lines only
SECTION_BUDGET = 0.15                     # share of total bytes, non-ledger
REFERENCE_BUDGET = 0.35
REFERENCE_HEADINGS = ("entities", "agent surfaces", "conventions")
LEDGER_HEADINGS = ("gotchas", "deferred", "migrations")
STAMP_RX = re.compile(r"^(> .*Last revision: ).*$", re.M)
# ----------------

DATE_RX = re.compile(r"\(20\d\d-\d\d-\d\d")
SHIPPED_RX = re.compile(r"\b(SHIPPED|shipped|DONE|done)\b")
TRIGGER_RX = re.compile(r"do when", re.I)
ITEM_RX = re.compile(r"^\s*\d+\.\s")
INV_ID_RX = re.compile(r"\{#(inv-[a-z0-9-]+)\}|\(`(inv-[a-z0-9-]+)`\)")

def sections(lines):
    out, name, start = [], "(preamble)", 0
    for i, ln in enumerate(lines):
        if ln.startswith("## "):
            out.append((name, start, i)); name, start = ln[3:].strip(), i
    out.append((name, start, len(lines)))
    return out

def has(name, keys): return any(k in name.lower() for k in keys)
def nbytes(lines): return sum(len(l.encode()) + 1 for l in lines)

def git_last_change():
    try:
        out = subprocess.run(["git", "log", "-1", "--format=%cs %h", "--", str(SYSTEM_MD)],
                             capture_output=True, text=True, check=True).stdout.strip()
        return out or date.today().isoformat()
    except Exception:
        return date.today().isoformat()

def main():
    text = SYSTEM_MD.read_text()
    lines = text.splitlines()
    secs = sections(lines)
    total = nbytes(lines)
    errs, warns = [], []
    sizes = {n: nbytes(lines[a:b]) for n, a, b in secs}

    if "--stamp" in sys.argv:
        new = STAMP_RX.sub(lambda m: m.group(1) + git_last_change() + " (gate-written).", text, count=1)
        if new != text:
            SYSTEM_MD.write_text(new); print("stamp written")
        else:
            print("no 'Last revision:' line found to stamp")
        return 0

    base = json.loads(SIDECAR.read_text()) if SIDECAR.exists() else {}
    prev_cands = base.get("extraction_candidates", [])

    # byte cap, two thresholds; name the extraction candidate
    ref = [(n, s) for n, s in sizes.items() if has(n, REFERENCE_HEADINGS)]
    cand = max(ref, key=lambda t: t[1])[0] if ref else None
    hint = f" — extraction candidate: '{cand}' ({sizes[cand]:,} B) → docs/ with an index left behind" if cand else ""
    if total > CAP_BYTES:
        errs.append(f"{total:,} B > cap {CAP_BYTES:,} B ({len(lines)} lines); groom or extract before "
                    f"feature work; raise the cap only after that fails, with --reason{hint}")
    elif total > CAP_BYTES * WARN_AT:
        warns.append(f"{total:,}/{CAP_BYTES:,} B ({total/CAP_BYTES:.0%}, {len(lines)} lines) — plan an "
                     f"extraction now, not under fail pressure{hint}")
    if LEVEL in ("medium", "large") and cand and prev_cands[-2:] == [cand, cand]:
        errs.append(f"'{cand}' has been the extraction candidate across the last two baselines — "
                    f"a warning that persists is no longer advice; extract it or record why not")

    in_code = False
    for name, a, b in secs:
        body = lines[a:b]
        for j, ln in enumerate(body, a + 1):
            if ln.startswith("```"): in_code = not in_code
            if in_code or ln.lstrip().startswith("|"): continue
            if len(ln) > LONG_LINE:
                warns.append(f"line {j} is {len(ln)} chars — reflow; width is not compression")
        if not has(name, LEDGER_HEADINGS) and name != "(preamble)":
            for j, ln in enumerate(body, a + 1):
                if DATE_RX.search(ln):
                    errs.append(f"date in descriptive section '{name}' line {j}: integrate, don't append")
        if has(name, ("deferred",)):
            for j, ln in enumerate(body, a + 1):
                if SHIPPED_RX.search(ln):
                    errs.append(f"shipped item still in Deferred line {j}: delete it")
                if ITEM_RX.match(ln) and not TRIGGER_RX.search(ln):
                    warns.append(f"Deferred line {j} has no 'do when' trigger — add one or delete")

    if LEVEL in ("medium", "large"):
        for name, s in sizes.items():
            if has(name, LEDGER_HEADINGS) or name == "(preamble)": continue
            budget = REFERENCE_BUDGET if has(name, REFERENCE_HEADINGS) else SECTION_BUDGET
            if s > total * budget:
                errs.append(f"'{name}' {s:,}/{total:,} B ({s/total:.0%}) over its {budget:.0%} budget — groom or extract")

    if LEVEL == "large":
        ids = {m.group(1) or m.group(2) for m in INV_ID_RX.finditer(text)}
        pins = json.loads(ENFORCEMENT_MAP.read_text()) if ENFORCEMENT_MAP.exists() else {}
        for inv in sorted(ids - set(pins)):
            warns.append(f"invariant {inv} has an id but no enforcement pin — it reads as checked and is not; "
                         f"pin it or demote it to a convention note")
        for inv, spec in pins.items():
            tgt = Path(spec["path"])
            if not tgt.exists():
                errs.append(f"invariant {inv}: enforcement point {tgt} is gone — doc promises what code no longer does")
            elif spec.get("symbol") and spec["symbol"] not in tgt.read_text():
                errs.append(f"invariant {inv}: symbol '{spec['symbol']}' missing from {tgt}")

    if "--update-baselines" in sys.argv:
        reason = sys.argv[sys.argv.index("--reason") + 1] if "--reason" in sys.argv else None
        if LEVEL == "large" and not reason:
            print('FAIL: --update-baselines requires --reason "<text>"'); return 1
        hist = (prev_cands + [cand])[-3:] if cand else prev_cands
        SIDECAR.write_text(json.dumps({"total_bytes": total, "lines": len(lines), "sections": sizes,
                                       "extraction_candidates": hist, "reason": reason}, indent=2))
        print(f"baselines updated → {SIDECAR}"); return 0

    for w in warns: print(f"WARN: {w}")
    for e in errs: print(f"FAIL: {e}")
    if errs:
        print("\nContract: integrate don't append; ledgers shrink; caps are earned.")
        return 1
    print(f"OK ({LEVEL}): {total:,}/{CAP_BYTES:,} B, {len(lines)} lines, {len(warns)} warnings")
    return 0

if __name__ == "__main__":
    sys.exit(main())
